package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Integer;
    attribute accumulated : Integer := 0;
    attribute serialTrig : Boolean := false;
    perform action tick {
      first start;
      then assign accumulated := accumulated + io_1;
      then if accumulated >= 1000 {
        first start;
        then assign accumulated := accumulated - 1000;
        then assign serialTrig := true;
      } else {
        first start;
        then assign serialTrig := false;
      }
    }
    out attribute serial_0_trigger : Boolean = serialTrig;
    out attribute serial_0_value_0 : Real = io_0;
  }
  part system : Controller;
}
